text:
{
  "headline": "FDA's records trace our supply to plants with multiple OAI and VAI inspections and recalls before and after the 2022-01-13 shortage posting",
  "headline_cites": ["D13", "D14", "D15", "D16", "D17", "D24", "E20", "E22", "E26", "E32", "E35", "E38", "E46", "E48", "E58", "E61", "E63", "E65", "E66", "E90", "E91", "E92", "E93", "E95", "E96"],
  "sentences": [
    {
      "text": "FDA first posted the dextrose monohydrate shortage on 2022-01-13 and it remains current as of 2026-10-21.",
      "cites": ["E117", "E109", "E110", "E111", "E113"]
    },
    {
      "text": "The shortage list includes Amphastar Pharmaceuticals, B. Braun Medical Inc., Baxter Healthcare, Hospira Inc., Otsuka ICU Medical LLC, and Fresenius Kabi USA.",
      "cites": ["E109", "E110", "E111", "E113", "E114", "E112"]
    },
    {
      "text": "B. Braun's US Pharmaceutical Manufacturing plant (FEI 2021236) received an OAI classification letter on 2020-10-22, 448 days before the shortage posting, and a subsequent OAI inspection ended 2025-11-21.",
      "cites": ["D24", "E20", "E22", "E26", "E28"]
    },
    {
      "text": "Baxter Healthcare plants (FEI 1025114, 1416980, 2618677, 2649614) have multiple OAI inspections, including 2012-11-16, 2016-02-26, 2024-02-09, 2024-08-01, 2026-04-02, 2010-08-26, 2013-04-19, 2014-02-11, 2015-05-01, and 2016-10-03.",
      "cites": ["E32", "E35", "E38", "E46", "E48", "E58", "E61", "E63", "E65", "E66"]
    },
    {
      "text": "Hospira Inc. (FEI 1021343) had OAI inspections ending 2010-01-19, 2011-06-17, and 2011-08-04, with a VAI inspection ending 2019-11-21, 784 days before the shortage posting.",
      "cites": ["E79", "E81", "E83", "D13", "E87"]
    },
    {
      "text": "Class I recall D-1257-2020 by B. Braun (2020-04-18) and Class II recalls by Baxter (2020-10-07) and B. Braun (2023-03-01, 2023-05-09) and Baxter (2023-03-15, 2023-08-11) involve dextrose-containing products.",
      "cites": ["D14", "D15", "D18", "D19", "D20", "D21", "E90", "E91", "E92", "E93", "E95", "E96"]
    },
    {
      "text": "Corvale East has 2.4 days of 50 g/1000 mL 250 mL bags on hand; Corvale General has 16.7 days and can transfer 89 bags to bring Corvale East to 5 days while keeping two weeks at General.",
      "cites": ["D1", "D2", "D26"]
    }
  ]
}
